// Display-only candidate vocabulary for the pinned Polaris-2026 snapshot.
// Generated from the independent semantic review. No row/phase/Equinox joins.
// Review status describes labels, not authentication of historical observations.
// Preserve raw identifiers, source values, nulls and source versions in storage/export.
const freezeDeep = value => {
  if (value && typeof value === 'object') {
    for (const child of Object.values(value)) freezeDeep(child);
    Object.freeze(value);
  }
  return value;
};
